alter table public.rate_limit_buckets enable row level security;
create index if not exists idx_legacy_transactions_company_date on public.transactions(company_id,date) where deleted_at is null;
create index if not exists idx_legacy_transactions_company_competencia on public.transactions(company_id,competencia) where deleted_at is null;
create index if not exists idx_legacy_transactions_company_category on public.transactions(company_id,category_id) where deleted_at is null;
create index if not exists idx_legacy_sales_company_period on public.sales(company_id,period_start,period_end) where deleted_at is null;
create index if not exists idx_legacy_categories_company on public.categories(company_id);
create index if not exists idx_legacy_erp_mappings_company_code on public.erp_account_mappings(company_id,erp_code);
create index if not exists idx_legacy_bank_accounts_company on public.bank_accounts(company_id);
create index if not exists idx_legacy_inventory_company_day on public.inventory_snapshots(company_id,snapshot_date) where deleted_at is null;
create index if not exists idx_legacy_members_user on public.company_members(user_id);
alter table public.transactions add constraint transactions_company_fk foreign key(company_id) references public.companies(id);
alter table public.transactions add constraint transactions_category_fk foreign key(category_id) references public.categories(id);
alter table public.transactions add constraint transactions_bank_account_fk foreign key(bank_account_id) references public.bank_accounts(id);
alter table public.transactions add constraint transactions_cost_center_fk foreign key(cost_center_id) references public.cost_centers(id);
alter table public.sales add constraint sales_company_fk foreign key(company_id) references public.companies(id);
alter table public.bank_accounts add constraint bank_accounts_company_fk foreign key(company_id) references public.companies(id);
alter table public.categories add constraint categories_company_fk foreign key(company_id) references public.companies(id);
alter table public.erp_account_mappings add constraint erp_mappings_company_fk foreign key(company_id) references public.companies(id);
alter table public.goals add constraint goals_company_fk foreign key(company_id) references public.companies(id);
alter table public.inventory_snapshots add constraint inventory_company_fk foreign key(company_id) references public.companies(id);
